world_checks.check_contacts_unique_and_linked:
def check(world):
    s = world.state()
    seen = {}
    for c in s.get("contacts", []):
        if c["email_normalized"] != c["email"].strip().lower():
            return f"contact {c['contact_id']} has email_normalized {c['email_normalized']!r} for {c['email']!r}"
        if c["email_normalized"] in seen:
            return f"contacts {seen[c['email_normalized']]} and {c['contact_id']} share {c['email_normalized']}"
        seen[c["email_normalized"]] = c["contact_id"]
    accounts = {a["account_id"] for a in s.get("accounts", [])}
    contacts = {c["contact_id"]: c for c in s.get("contacts", [])}
    for c in contacts.values():
        if c["account_id"] not in accounts:
            return f"contact {c['contact_id']} names unknown account {c['account_id']}"
    reps = {r["rep_id"] for r in s.get("reps", [])}
    queues = {q["queue_id"] for q in s.get("queues", [])}
    for l in s.get("leads", []):
        c = contacts.get(l["contact_id"])
        if not c or c["account_id"] != l["account_id"]:
            return f"lead {l['lead_id']} does not match its contact and account"
        if l["owner_rep_id"] and l["owner_rep_id"] not in reps:
            return f"lead {l['lead_id']} has unknown owner {l['owner_rep_id']}"
        if l["queue_id"] and l["queue_id"] not in queues:
            return f"lead {l['lead_id']} has unknown queue {l['queue_id']}"
    return None

world_checks.check_routing_matches_territories:
def check(world):
    s = world.state()
    rules = {r["country"].lower(): r["rep_id"] for r in s.get("territory_rules", [])}
    params = {p["name"]: p["value"] for p in s.get("environment_policy", [])}
    fallback = params.get("fallback_queue", '"Q-SDR-FALLBACK"').strip('"')
    if fallback not in {q["queue_id"] for q in s.get("queues", [])}:
        return f"fallback queue {fallback} is not a queue"
    for l in s.get("leads", []):
        if l["owner_rep_id"] and rules.get((l["country"] or "").lower()) != l["owner_rep_id"]:
            return f"lead {l['lead_id']} in {l['country']} is owned by {l['owner_rep_id']}, territory says {rules.get((l['country'] or '').lower())}"
        if l["queue_id"] and (l["country"] or "").lower() in rules:
            return f"lead {l['lead_id']} sits in a queue though {l['country']} has an owner"
    return None

world_checks.check_demos_on_owner_calendars:
def check(world):
    s = world.state()
    reps = {r["rep_id"]: r for r in s.get("reps", [])}
    events = {e["event_id"]: e for e in s.get("calendar_events", [])}
    slots = {x["slot_id"]: x for x in s.get("demo_slots", [])}
    leads = {l["lead_id"]: l for l in s.get("leads", [])}
    for d in s.get("demos", []):
        if d["status"] != "booked":
            continue
        e = events.get(d["calendar_event_id"])
        if not e or e["calendar_id"] != reps[d["rep_id"]]["calendar_id"] or e["status"] == "cancelled":
            return f"demo {d['demo_id']} has no live event on {d['rep_id']}'s calendar"
        slot = slots.get(d["slot_id"])
        if not slot or slot["rep_id"] != d["rep_id"] or slot["status"] != "booked" or slot["start_time"] != e["start_time"]:
            return f"demo {d['demo_id']} does not match its slot"
        if leads[d["lead_id"]]["owner_rep_id"] != d["rep_id"]:
            return f"demo {d['demo_id']} is not on the lead owner's calendar"
    for c in s.get("calendar_calendars", []):
        if c["calendar_id"].startswith("CAL-A") and c["access_role"] != "reader":
            return f"{c['calendar_id']} must be read-only for the desk: demos are booked with book_demo"
    return None

world_checks.check_consent_and_outreach:
def check(world):
    s = world.state()
    contacts = {c["contact_id"]: c for c in s.get("contacts", [])}
    for o in s.get("outreach_queue", []):
        if contacts[o["contact_id"]]["consent_status"] == "opted_out" and o["status"] == "planned":
            return f"outreach {o['item_id']} is planned for opted-out contact {o['contact_id']}"
    logged = {e["contact_id"] for e in s.get("consent_log", []) if e["status"] == "opted_out"}
    for c in contacts.values():
        if c["consent_status"] == "opted_out" and c["contact_id"] not in logged:
            return f"contact {c['contact_id']} is opted out with no consent record"
    return None

world_checks.check_mailbox_and_slack_linked:
def check(world):
    import re
    s = world.state()
    emails = {c["email_normalized"] for c in s.get("contacts", [])} | {r["email"] for r in s.get("reps", [])} | {"sales@brightdesk.example", "legal@brightdesk.example", "growth@leadsfast.example"}
    for m in s.get("gmail_messages", []):
        if m["sender"].strip().lower() not in emails:
            return f"message {m['id']} comes from unknown sender {m['sender']}"
    leads = {l["lead_id"] for l in s.get("leads", [])}
    for m in s.get("gmail_messages", []) + [{"id": x["message_id"], "body": x["text"]} for x in s.get("slack_messages", [])]:
        for lid in re.findall(r"\b(L\d{2})\b", m["body"]):
            if lid not in leads:
                return f"{m['id']} names unknown lead {lid}"
    threads = {t["id"] for t in s.get("gmail_threads", [])}
    for d in s.get("gmail_drafts", []):
        if d["thread_id"] not in threads:
            return f"draft {d['id']} is on unknown thread"
    users = {u["user_id"] for u in s.get("slack_users", [])}
    for m in s.get("slack_messages", []):
        if m["user_id"] not in users:
            return f"Slack message {m['message_id']} from unknown user"
    actor = (s.get("current_actor") or [{}])[0].get("user_id")
    if actor != "U_SALESDESK":
        return "the desk is not the current actor"
    return None

world_checks.check_parameters_match_policy:
def check(world):
    import json
    s = world.state()
    params = {p["name"]: json.loads(p["value"]) for p in s.get("environment_policy", [])}
    want = {"fallback_queue": "Q-SDR-FALLBACK", "min_qualifying_seats": 20, "demo_minutes": 30, "allowed_destinations": "CH_SALESHANDOFF", "mode": "approval_gated", "max_length": 4000}
    for k, v in want.items():
        if params.get(k) != v:
            return f"parameter {k} is {params.get(k)!r}, policy default {v!r}"
    for x in s.get("demo_slots", []):
        from datetime import datetime
        a = datetime.fromisoformat(x["start_time"].replace("Z", "+00:00")); b = datetime.fromisoformat(x["end_time"].replace("Z", "+00:00"))
        if (b - a).seconds // 60 != params["demo_minutes"]:
            return f"slot {x['slot_id']} is not {params['demo_minutes']} minutes"
    return None

world_checks.check_people_and_sessions_consistent:
def check(world):
    s = world.state()
    contacts = {c["contact_id"]: c for c in s.get("contacts", [])}
    contact_names = {c["name"].strip().lower() for c in contacts.values()}
    contact_emails = {c["email_normalized"] for c in contacts.values()}
    domains = {}
    for a in s.get("accounts", []):
        if a["domain"] in domains:
            return f"accounts {domains[a['domain']]} and {a['account_id']} share the domain {a['domain']}"
        domains[a["domain"]] = a["account_id"]
    names, emails = {}, {}
    for u in s.get("slack_users", []):
        name, email = u["name"].strip().lower(), u["email"].strip().lower()
        if name in names or email in emails:
            return f"Slack users {names.get(name) or emails.get(email)} and {u['user_id']} are the same person twice"
        if name in contact_names or email in contact_emails:
            return f"employee {u['user_id']} ({u['name']}) is also a contact: one person, two records"
        names[name], emails[email] = u["user_id"], u["user_id"]
    users = {u["user_id"] for u in s.get("slack_users", [])}
    sessions = s.get("session_caller", [])
    if [r["id"] for r in sessions] != ["default"]:
        return "session_caller must hold exactly the default row"
    person = sessions[0]["person_id"]
    if person and person not in contacts and person not in users:
        return f"the person in the conversation, {person}, is neither a contact nor an employee"
    return None

world_checks.check_no_double_bookings:
def check(world):
    s = world.state()
    live = sorted((e for e in s.get("calendar_events", []) if e["status"] != "cancelled"), key=lambda e: (e["calendar_id"], e["start_time"]))
    for a, b in zip(live, live[1:]):
        if a["calendar_id"] == b["calendar_id"] and b["start_time"] < a["end_time"]:
            return f"events {a['event_id']} and {b['event_id']} overlap on {a['calendar_id']}"
    held = {}
    for d in s.get("demos", []):
        if d["status"] != "booked":
            continue
        if d["slot_id"] in held:
            return f"demos {held[d['slot_id']]} and {d['demo_id']} are both booked in slot {d['slot_id']}"
        held[d["slot_id"]] = d["demo_id"]
    for x in s.get("demo_slots", []):
        if x["status"] == "booked" and x["slot_id"] not in held:
            return f"slot {x['slot_id']} is booked with no booked demo in it"
    return None
